import{_ as a,o as t,c as s,a6 as o}from"./chunks/framework.4tsfTCyC.js";const u=JSON.parse('{"title":"Research Tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/research-tools.md","filePath":"guide/research-tools.md"}'),r={name:"guide/research-tools.md"};function n(i,e,d,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="research-tools" tabindex="-1">Research Tools <a class="header-anchor" href="#research-tools" aria-label="Permalink to &quot;Research Tools&quot;">​</a></h1><p>You&#39;re deep in a manuscript and realize you need to cite &quot;that attention paper from 2017&quot; but can&#39;t remember the exact title. Or you want to verify that an integral in your appendix is correct. Or you need to pull twenty BibTeX entries from your Zotero library into a new project. TeXRA&#39;s research agents handle all of this without leaving VS Code.</p><h2 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What You Can Do&quot;">​</a></h2><h3 id="find-papers" tabindex="-1">Find Papers <a class="header-anchor" href="#find-papers" aria-label="Permalink to &quot;Find Papers&quot;">​</a></h3><p>Ask any research agent to search for papers. TeXRA searches <strong>arXiv</strong> (preprints) and <strong>Crossref</strong> (published works) automatically:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find recent papers on transformer architectures for document understanding.</span></span>
<span class="line"><span>Focus on work from 2023-2024 that handles mathematical equations.</span></span></code></pre></div><p><strong>User story:</strong> A postdoc is writing a related-work section for a NeurIPS submission. She opens the <code>search</code> agent and asks for papers on &quot;efficient self-attention for long documents.&quot; In seconds she has a table of relevant arXiv preprints with titles, authors, and abstracts—ready to cite.</p><h3 id="look-up-citations" tabindex="-1">Look Up Citations <a class="header-anchor" href="#look-up-citations" aria-label="Permalink to &quot;Look Up Citations&quot;">​</a></h3><p>Give a DOI or arXiv ID to get full bibliographic details:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Get the citation info for arxiv:2401.12345</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Look up DOI 10.1038/nature12373</span></span></code></pre></div><h3 id="download-paper-sources" tabindex="-1">Download Paper Sources <a class="header-anchor" href="#download-paper-sources" aria-label="Permalink to &quot;Download Paper Sources&quot;">​</a></h3><p>For deeper analysis, ask to download the LaTeX source of a paper:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download the source files for arxiv:2401.12345 so I can see how they made their figures.</span></span></code></pre></div><h3 id="search-the-web" tabindex="-1">Search the Web <a class="header-anchor" href="#search-the-web" aria-label="Permalink to &quot;Search the Web&quot;">​</a></h3><p>For documentation, project pages, or general info:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find the official PyTorch documentation for attention mechanisms.</span></span></code></pre></div><h3 id="manage-references-with-zotero" tabindex="-1">Manage References with Zotero <a class="header-anchor" href="#manage-references-with-zotero" aria-label="Permalink to &quot;Manage References with Zotero&quot;">​</a></h3><p>If you use <a href="https://www.zotero.org/" target="_blank" rel="noreferrer">Zotero</a> with the <a href="https://retorque.re/zotero-better-bibtex/" target="_blank" rel="noreferrer">Better BibTeX</a> plugin, TeXRA can search, export, and add items to your library directly. Just make sure Zotero is running when you use these features.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Search my Zotero library for papers by Vaswani on attention mechanisms.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Export the selected Zotero items as a .bib file for my project.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add this arXiv paper to my Zotero library.</span></span></code></pre></div><p><strong>User story:</strong> A PhD student is collecting references for a thesis chapter. She asks the <code>search</code> agent to find key papers on graph neural networks, then says &quot;add these to my Zotero and export them to <code>references.bib</code>.&quot; The agent handles the lookup, adds entries to her Zotero library, and writes the BibTeX file—all in one conversation.</p><div class="tip custom-block"><p class="custom-block-title">Default Bibliography Path</p><p>Set <code>texra.bib.defaultPath</code> in your VS Code settings to specify where Zotero exports land by default, so agents always know where to save bibliography entries.</p></div><h2 id="which-agent-to-use" tabindex="-1">Which Agent to Use <a class="header-anchor" href="#which-agent-to-use" aria-label="Permalink to &quot;Which Agent to Use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Agent</th><th>Best for</th></tr></thead><tbody><tr><td><code>search</code></td><td>Finding papers, literature reviews, fact-checking</td></tr><tr><td><code>research</code></td><td>Computational verification with Wolfram and literature</td></tr><tr><td><code>discuss</code></td><td>Brainstorming research directions with literature context</td></tr><tr><td><code>ask</code></td><td>Quick lookups about your documents and related work</td></tr></tbody></table>`,26)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
